/* generic function for a non params report */
int __trace_generic_no_params_func(INT16 moduleID, UINT16 reportID)
{
	if(!PASS_FILTER(reportID)) return DIAG_INVALID_MODULE_ID;
	diag_lock_G();
	bMiniLog = 0;
	global_trace_desc_t_no_params. moduleID = moduleID;
	global_trace_desc_t_no_params. reportID = reportID;
	/*global_trace_desc_t_no_params. numOfParams is always zero!*/
	diagTraceDesc = (DiagTraceDescriptor*)& global_trace_desc_t_no_params;
	return 1;
}

/* generic function for a mini non params report */
int __trace_generic_mini_no_params_func(INT16 moduleID, UINT16 reportID, UINT8 miniInfo)
{
	if(!PASS_FILTER(reportID)) return DIAG_INVALID_MODULE_ID;
	diag_lock_G();
	bMiniLog = 1;
	global_trace_desc_t_mini_no_params. moduleID = moduleID;
	global_trace_desc_t_mini_no_params. reportID = reportID;
	global_trace_desc_t_mini_no_params. miniInfo = miniInfo;
	/*global_trace_desc_t_no_params. numOfParams is always zero!*/
	miniDiagTraceDesc = (MiniDiagTraceDescriptor*)& global_trace_desc_t_mini_no_params;
	return 1;
}

